export const localGuidePaths = new Set(guides.map(g=>g._localTemplate));
export const localGuideImages = new Set(guides.map(g=>g.image.localPath));
const priority = ["sikringen-gar", "elbillader", "elkontroll", "sikringsskap", "oppussing", "gjore-selv", "skjoteledninger", "komfyrvakt", "dimmer-led", "utebelysning", "downlights", "fargetemperatur", "watt-lumen-lux", "ip-grad"];
export function sortGuides(guides){return [...guides].sort((a,b)=>{
 const rank=guide=>{const value=priority.indexOf(guide.slug?.current);return value<0?priority.length:value;};
 return rank(a)-rank(b);
});}
export function withLocalGuides(documents){
 const active=documents.filter(d=>!d.cmsMigrationTarget&&!d._id.startsWith('drafts.')&&!d._id.startsWith('versions.'));
 return [...documents,...guides.filter(g=>!active.some(d=>d._type==='guide'&&d.slug?.current===g.slug.current))];
}
